<template>
  <ion-page>
    <ion-content :fullscreen="true">
      <main class="admin-shell"><button v-if="menuOpen" class="nav-scrim" aria-label="Close navigation" @click="menuOpen = false"></button><aside id="admin-sidebar" class="sidebar" :class="{ 'mobile-open': menuOpen }"><BrandMark /><nav @click="menuOpen = false"><p>OVERVIEW</p><a href="/admin" :class="{ active: section === 'dashboard' }"><ion-icon :icon="gridOutline" />Dashboard</a><p>WORKSPACE</p><a v-for="item in navGroups[0].items" :key="item.key" :class="{ active: section === item.key }" :href="`/admin/${item.key}`"><ion-icon :icon="item.icon" />{{ item.label }}<b v-if="item.key === 'bookings'">{{ databaseBookings.length }}</b></a><p>FERRY OPERATIONS</p><a v-for="item in navGroups[1].items" :key="item.key" :class="{ active: section === item.key }" :href="`/admin/${item.key}`"><ion-icon :icon="item.icon" />{{ item.label }}</a><p>PASSENGER OPERATIONS</p><a v-for="item in navGroups[2].items" :key="item.key" :class="{ active: section === item.key }" :href="`/admin/${item.key}`"><ion-icon :icon="item.icon" />{{ item.label }}</a><p>MANAGEMENT</p><a v-for="item in navGroups[3].items" :key="item.key" :class="{ active: section === item.key }" :href="`/admin/${item.key}`"><ion-icon :icon="item.icon" />{{ item.label }}</a></nav><button class="exit" type="button" @click="logout"><ion-icon :icon="logOutOutline" aria-hidden="true" />Log out</button></aside><section class="workspace"><header><button class="mobile-menu" :aria-expanded="menuOpen" aria-controls="admin-sidebar" aria-label="Toggle navigation" @click="menuOpen = !menuOpen"><ion-icon :icon="menuOpen ? closeOutline : menuOutline" /></button><span class="breadcrumbs">Operations <ion-icon :icon="chevronForwardOutline" aria-hidden="true" /> <strong>{{ current.title }}</strong></span><div class="header-actions"><ion-icon :icon="searchOutline" /><ion-icon :icon="notificationsOutline" /><span class="profile-chip" aria-label="Admin profile"><span class="mini-avatar">AU</span><span>Admin User</span></span></div></header><main class="content"><div class="heading"><div><p class="kicker">{{ current.eyebrow }}</p><h1>{{ current.title }}</h1><p>{{ current.description }}</p></div><ion-button v-if="current.action && ['check-in','boarding','manifest','reports','users'].includes(section)" class="primary" @click="handleAdminAction"><ion-icon slot="start" :icon="addOutline" />{{ current.action }}</ion-button></div><p v-if="databaseError" class="database-error" role="alert">{{ databaseError }}</p><section v-if="section === 'dashboard'" class="dashboard"><div class="metrics"><article v-for="metric in metrics" :key="metric.label"><span :class="metric.tone"><ion-icon :icon="metric.icon" /></span><div><small>{{ metric.label }}</small><strong>{{ metric.value }}</strong><em>{{ metric.note }}</em></div></article></div><div class="lower-grid"><article class="panel"><div class="panel-title"><div><p class="kicker">LIVE OPERATIONS</p><h2>Today's trips</h2></div><a href="/admin/trips">View all <ion-icon :icon="arrowForwardOutline" /></a></div><div class="table-scroll live-trips-scroll"><table class="live-trips-table"><thead><tr><th>Trip</th><th>Route</th><th>Vessel</th><th>Departure</th><th>Booked</th><th>Status</th></tr></thead><tbody><tr v-for="trip in liveTrips" :key="trip.code"><td><strong>{{ trip.code }}</strong></td><td><div class="live-route"><span>{{ trip.from }}</span><ion-icon :icon="arrowForwardOutline" aria-hidden="true" /><span>{{ trip.to }}</span></div></td><td>{{ trip.vessel }}</td><td>{{ trip.time }}</td><td><div class="booked-cell"><strong>{{ trip.booked }} <small>/ {{ trip.capacity }}</small></strong><span class="capacity-track"><i :style="{ width: `${trip.percent}%` }"></i></span></div></td><td><span class="table-status" :class="trip.status.toLowerCase()"><ion-icon :icon="trip.status === 'BOARDING' ? boatOutline : checkmarkCircleOutline" aria-hidden="true" />{{ trip.status }}</span></td></tr><tr v-if="!liveTrips.length"><td colspan="6" class="empty-row">No sailings scheduled for today.</td></tr></tbody></table></div></article><article class="panel flow-panel"><p class="kicker">TERMINAL HEALTH</p><h2>Passenger flow</h2><div class="donut" :style="{ background: 'conic-gradient(var(--ocean) 0 ' + boardingPercent + '%,var(--surface-soft) ' + boardingPercent + '% 100%)' }"><strong>{{ boardingPercent }}%</strong><span>checked in</span></div><div class="legend"><span><i></i>Checked-in <b>{{ checkedInCount }}</b></span><span><i></i>Boarded <b>{{ boardedCount }}</b></span><span><i></i>Remaining <b>{{ remainingCount }}</b></span></div></article></div></section><section v-else class="module"><div class="toolbar"><div class="search-box"><ion-icon :icon="searchOutline" /><input v-if="section === 'bookings'" v-model="bookingSearch" type="search" placeholder="Search reference, passenger, route, status" aria-label="Search bookings" /><input v-else-if="section === 'passengers'" v-model="passengerSearch" type="search" placeholder="Search name, booking, sailing, account" aria-label="Search passengers" /><span v-else>Search {{ current.title.toLowerCase() }}</span></div><div class="filters"><template v-if="section === 'bookings'"><select v-model="bookingStatusFilter" aria-label="Filter bookings by status"><option value="ALL">All statuses</option><option value="CONFIRMED">Confirmed</option><option value="PENDING">Pending</option><option value="CANCELLED">Cancelled</option></select><button type="button" @click="loadAdminData">Refresh</button></template><template v-else-if="section === 'passengers'"><select v-model="passengerStatusFilter" aria-label="Filter passenger tickets by status"><option value="ALL">All ticket statuses</option><option value="ISSUED">Issued</option><option value="CHECKED_IN">Checked in</option><option value="BOARDED">Boarded</option><option value="CANCELLED">Cancelled</option></select><button type="button" @click="loadAdminData">Refresh</button></template><template v-else><button>All statuses <ion-icon :icon="chevronDownOutline" /></button><button>Today <ion-icon :icon="chevronDownOutline" /></button></template><ion-button v-if="current.action && ['check-in','boarding','manifest','reports','users'].includes(section)" class="primary" @click="handleAdminAction"><ion-icon slot="start" :icon="addOutline" />{{ current.action }}</ion-button></div></div><article class="panel table-panel"><div class="panel-title"><div><p class="kicker">LIVE DATABASE</p><h2>{{ current.tableTitle }}</h2></div><span class="record-count">{{ current.count }} records</span></div><div class="table-scroll"><table><thead><tr><th v-for="column in current.columns" :key="column">{{ column }}</th><th v-if="!['users','passengers'].includes(section)">Action</th></tr></thead><tbody><tr v-if="!current.rows.length"><td :colspan="current.columns.length + (!['users','passengers'].includes(section) ? 1 : 0)" class="empty-row">No matching records found.</td></tr><tr v-for="row in current.rows" :key="row[0]"><td v-for="cell in row" :key="cell">{{ cell }}</td><td v-if="!['users','passengers'].includes(section)"><button v-if="section === 'bookings'" class="cancel-row" :disabled="row[5] !== 'CONFIRMED' || cancellingReference === row[0]" @click="cancelBookingByReference(String(row[0]))"><ion-icon :icon="closeOutline" />{{ cancellingReference === row[0] ? 'Cancelling…' : 'Cancel' }}</button><button v-else class="row-action"><ion-icon :icon="ellipsisHorizontal" /></button></td></tr></tbody></table></div><div class="pagination"><span v-if="['bookings','passengers'].includes(section)">Showing {{ current.rows.length }} {{ section === 'bookings' ? 'matching reservations' : 'passengers from the latest 1,000 passenger records' }}</span><span v-else>Showing 1-{{ current.rows.length }} of {{ current.count }}</span><template v-if="!['bookings','passengers'].includes(section)"><button>‹</button><button class="current-page">1</button><button>›</button></template></div></article></section><p class="mock-note"><ion-icon :icon="informationCircleOutline" /> Live reservations, sailing capacity, and user accounts are loaded from PostgreSQL through SQL Connect.</p><ion-modal :is-open="showActionModal" @didDismiss="showActionModal = false"><div class="admin-action-modal"><button class="close-action" aria-label="Close" @click="showActionModal = false"><ion-icon :icon="closeOutline" /></button><span class="action-modal-icon"><ion-icon :icon="addOutline" /></span><p class="kicker">PROTOTYPE DATA</p><h2>{{ current.action }}</h2><p>Database creation actions are available after the admin write operations are configured.</p><label>{{ section === 'ports' ? 'Port name' : section === 'users' ? 'Staff name' : 'Vessel name' }}<input v-model.trim="newRecordName" :placeholder="section === 'users' ? 'Enter staff name' : 'Enter a name'" @keyup.enter="createAdminRecord" /></label><ion-button expand="block" class="primary" :disabled="!newRecordName.trim()" @click="createAdminRecord">Close</ion-button></div></ion-modal><ion-modal :is-open="showUserModal" @didDismiss="closeUserModal"><section class="admin-action-modal user-create-modal" role="dialog" aria-labelledby="create-user-title"><button class="close-action" aria-label="Close dialog" @click="closeUserModal"><ion-icon :icon="closeOutline" /></button><span class="action-modal-icon"><ion-icon :icon="peopleCircleOutline" /></span><p class="kicker">USER MANAGEMENT</p><h2 id="create-user-title">Create an account</h2><p>Create a passenger or staff account. The selected role is applied to Firebase Authentication and PostgreSQL.</p><div v-if="createdAccount" class="account-created" role="status"><strong>Account created</strong><span>{{ createdAccount.email }} · {{ createdAccount.role }}</span><label>Temporary password<div class="password-copy-row"><code>{{ createdAccount.password }}</code><button type="button" @click="copyTemporaryPassword"><ion-icon :icon="copyOutline" />Copy</button></div></label><p>Share this password privately. The account holder can sign in and change it later.</p><ion-button expand="block" class="primary" @click="closeUserModal">Done</ion-button></div><form v-else class="user-create-form" @submit.prevent="createManagedUser"><label>Full name<input v-model.trim="userForm.fullName" autocomplete="name" maxlength="120" required placeholder="Full name" /></label><label>Email address<input v-model.trim="userForm.email" type="email" autocomplete="email" maxlength="254" required placeholder="name@example.com" /></label><label>Account role<select v-model="userForm.role" required><option value="PASSENGER">Passenger</option><option value="TICKETING">Ticketing staff</option><option value="BOARDING">Boarding staff</option></select></label><label>Temporary password<div class="password-generate-row"><input v-model="userForm.password" type="text" autocomplete="new-password" minlength="8" maxlength="128" required placeholder="At least 8 characters" /><button type="button" :disabled="generatingPassword" @click="generateUserPassword">{{ generatingPassword ? 'Generating…' : 'Generate' }}</button></div></label><p class="password-hint">The password is shown once after creation. Share it with the account holder privately.</p><p v-if="userError" class="user-form-error" role="alert">{{ userError }}</p><div class="user-form-actions"><ion-button fill="outline" type="button" @click="closeUserModal">Cancel</ion-button><ion-button class="primary" type="submit" :disabled="creatingUser || !userForm.fullName || !userForm.email || userForm.password.length < 8">{{ creatingUser ? 'Creating…' : 'Create account' }}</ion-button></div></form></section></ion-modal></main></section></main>
    </ion-content>
  </ion-page>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { signOut } from 'firebase/auth'
import { IonButton, IonContent, IonIcon, IonModal, IonPage } from '@ionic/vue'
import { httpsCallable } from 'firebase/functions'
import { addOutline, arrowForwardOutline, barChartOutline, boatOutline, chevronDownOutline, chevronForwardOutline, checkmarkCircleOutline, closeOutline, copyOutline, ellipsisHorizontal, gridOutline, informationCircleOutline, listOutline, locationOutline, logOutOutline, menuOutline, notificationsOutline, peopleCircleOutline, peopleOutline, scanOutline, searchOutline, ticketOutline } from 'ionicons/icons'
import BrandMark from '../../components/BrandMark.vue'
import { adminCancelBooking, adminDashboardStats, adminPassengerRecords, adminSailings, adminUsers, staffBookings, type AdminDashboardStatsData, type AdminPassengerRecordsData, type AdminSailingsData, type AdminUsersData, type StaffBookingsData } from '../dataconnect-generated/staff'
import { auth, functions, staffDataConnect } from '../services/firebase'
const route = useRoute()
const router = useRouter()
const menuOpen = ref(false)
async function logout() {
  menuOpen.value = false
  if (auth) await signOut(auth)
  await router.replace('/login')
}
const databaseBookings = ref<StaffBookingsData['bookings']>([])
const databaseSailings = ref<AdminSailingsData['sailings']>([])
const databaseUsers = ref<AdminUsersData['users']>([])
const passengerRecords = ref<AdminPassengerRecordsData['bookingPassengers']>([])
const dashboardStats = ref<AdminDashboardStatsData | null>(null)
const databaseError = ref('')
const showActionModal = ref(false)
const showUserModal = ref(false)
const bookingSearch = ref('')
const bookingStatusFilter = ref('ALL')
const passengerSearch = ref('')
const passengerStatusFilter = ref('ALL')
const cancellingReference = ref('')
const creatingUser = ref(false)
const generatingPassword = ref(false)
const userError = ref('')
const createdAccount = ref<{email:string;role:string;password:string}|null>(null)
const userForm = reactive({fullName:'',email:'',phone:'',role:'PASSENGER',password:''})
const newRecordName = ref('')
async function refreshAdminUsers(){if(!staffDataConnect)return;const result=await adminUsers(staffDataConnect);databaseUsers.value=result.data.users}
function localDayBounds(date = new Date()) { const start = new Date(date.getFullYear(), date.getMonth(), date.getDate()); const end = new Date(date.getFullYear(), date.getMonth(), date.getDate() + 1); return { dayStart: start.toISOString(), dayEnd: end.toISOString() } }
async function loadAdminData(){if(!staffDataConnect){databaseError.value='Firebase is not configured.';return}try{const [bookings,sailings,users,stats,passengers]=await Promise.all([staffBookings(staffDataConnect),adminSailings(staffDataConnect),adminUsers(staffDataConnect),adminDashboardStats(staffDataConnect,localDayBounds()),adminPassengerRecords(staffDataConnect)]);databaseBookings.value=bookings.data.bookings;databaseSailings.value=sailings.data.sailings;databaseUsers.value=users.data.users;dashboardStats.value=stats.data;passengerRecords.value=passengers.data.bookingPassengers;databaseError.value=''}catch(error){databaseError.value=(error as Error).message||'Could not load operations data.'}}
onMounted(() => { void loadAdminData() })
const section = computed(() => String(route.params.section || 'dashboard'))
const accountRoleLabel = (role:string) => ({PASSENGER:'Passenger',TICKETING:'Ticketing staff',BOARDING:'Boarding staff',ADMIN:'Administrator'}[role] || role)
const navGroups = [{items:[{key:'bookings',label:'Bookings',icon:ticketOutline},{key:'passengers',label:'Passengers',icon:peopleOutline}]},{items:[{key:'trips',label:'Trips & schedules',icon:boatOutline},{key:'ports',label:'Ports & routes',icon:locationOutline},{key:'vessels',label:'Vessels',icon:boatOutline}]},{items:[{key:'check-in',label:'Check-in',icon:scanOutline},{key:'boarding',label:'Boarding',icon:peopleOutline},{key:'manifest',label:'Passenger manifest',icon:listOutline}]},{items:[{key:'reports',label:'Reports & analytics',icon:barChartOutline},{key:'users',label:'Users',icon:peopleCircleOutline}]}]
const configs: Record<string, any> = { bookings:{eyebrow:'WORKSPACE',title:'Booking management',description:'Review, confirm, and manage passenger reservations.',tableTitle:'Recent bookings',count:356,columns:['Reference','Passenger','Route','Departure','Amount','Status'],rows:[['BL-2026-000125','Juan Dela Cruz','Calapan → Batangas','6:00 AM','PHP 832','CONFIRMED'],['BL-2026-000124','Maria Santos','Batangas → Calapan','9:30 AM','PHP 528','PAID'],['BL-2026-000123','Carlo Reyes','Calapan → Batangas','2:00 PM','PHP 498','PENDING']]},passengers:{eyebrow:'WORKSPACE',title:'Passenger management',description:'Passenger and ticket records loaded from PostgreSQL. Manage passenger accounts in Users.',tableTitle:'Passengers from recent bookings',count:0,columns:['Passenger','Type','Booking','Sailing','Booking account','Ticket status'],rows:[]},trips:{eyebrow:'FERRY OPERATIONS',title:'Trips & schedules',description:'Manage sailings, capacity, and departure status.',action:'Create trip',tableTitle:'Today\'s schedule',count:12,columns:['Trip','Route','Vessel','Departure','Booked','Status'],rows:[['TRP-001','Calapan → Batangas','MV Island Star','6:00 AM','280 / 300','BOARDING'],['TRP-002','Calapan → Batangas','MV Ocean Crest','9:30 AM','216 / 300','SCHEDULED'],['TRP-003','Batangas → Calapan','MV Verde Express','11:00 AM','188 / 250','SCHEDULED']]},ports:{eyebrow:'FERRY OPERATIONS',title:'Ports & routes',description:'Maintain the terminals and routes served by BarkoLink.',action:'Add port',tableTitle:'Port directory',count:6,columns:['Code','Port name','Location','Routes','Status'],rows:[['CAL','Calapan Port','Oriental Mindoro','04','ACTIVE'],['BTG','Batangas Port','Batangas','05','ACTIVE'],['PGA','Puerto Galera Port','Oriental Mindoro','02','ACTIVE']]},vessels:{eyebrow:'FERRY OPERATIONS',title:'Vessel management',description:'Monitor active vessels, capacity, and maintenance status.',action:'Add vessel',tableTitle:'Fleet directory',count:8,columns:['Vessel','Code','Capacity','Today\'s trips','Status'],rows:[['MV Island Star','MIS-001','300','02','ACTIVE'],['MV Ocean Crest','MOC-002','300','02','ACTIVE'],['MV Verde Express','MVE-003','250','01','MAINTENANCE']]},'check-in':{eyebrow:'PASSENGER OPERATIONS',title:'Passenger check-in',description:'Verify tickets and move passengers through the terminal.',action:'Scan QR code',tableTitle:'Check-in queue',count:280,columns:['Passenger','Ticket','Trip','Category','Status'],rows:[['Juan Dela Cruz','BL-TK-000125','TRP-001','Regular','CHECKED-IN'],['Maria Santos','BL-TK-000124','TRP-001','Student','CHECKED-IN'],['Carlo Reyes','BL-TK-000123','TRP-003','Senior Citizen','PENDING']]},boarding:{eyebrow:'PASSENGER OPERATIONS',title:'Boarding management',description:'Track boarding activity for every live sailing.',action:'Scan ticket',tableTitle:'Recent boarding activity',count:230,columns:['Passenger','Ticket','Trip','Boarding time','Status'],rows:[['Maria Santos','BL-TK-000124','TRP-001','5:24 AM','BOARDED'],['Ana Cruz','BL-TK-000119','TRP-001','5:18 AM','BOARDED'],['Leo Ramos','BL-TK-000118','TRP-001','Pending','CHECKED-IN']]},manifest:{eyebrow:'PASSENGER OPERATIONS',title:'Passenger manifest',description:'View the final passenger list for each trip.',action:'Export manifest',tableTitle:'TRP-001 · MV Island Star',count:280,columns:['No.','Passenger','Sex','Category','Ticket','Boarding'],rows:[['001','Juan Dela Cruz','M','Regular','BL-TK-000125','PENDING'],['002','Maria Santos','F','Student','BL-TK-000124','BOARDED'],['003','Ana Cruz','F','Regular','BL-TK-000119','BOARDED']]},reports:{eyebrow:'INSIGHTS',title:'Reports & analytics',description:'Explore mock booking, passenger, and vessel performance.',action:'Generate report',tableTitle:'Report library',count:6,columns:['Report','Period','Generated by','Updated','Status'],rows:[['Booking performance','September 2026','Admin User','Today','READY'],['Passenger volume','Q3 2026','Admin User','Yesterday','READY'],['Vessel utilization','September 2026','Admin User','Sep 28','READY']]},users:{eyebrow:'MANAGEMENT',title:'User management',description:'Create passenger and staff accounts with role-based access.',action:'Add user',tableTitle:'System users',count:18,columns:['Name','Email','Role','Last active','Status'],rows:[['Admin User','admin@barkolink.ph','Administrator','Now','ACTIVE'],['Mia Santos','mia@barkolink.ph','Ticketing Staff','10 min ago','ACTIVE'],['Paolo Cruz','paolo@barkolink.ph','Boarding Staff','Yesterday','ACTIVE']]}}
const current = computed(() => {
  const base = configs[section.value] || { eyebrow:'OPERATIONS OVERVIEW',title:'Dashboard',description:'Here is what is happening across BarkoLink today.',tableTitle:'Today\'s trips',count:12,columns:['Trip','Route','Vessel','Departure','Status'],rows:[] }
  const bookings = databaseBookings.value
  const sailings = databaseSailings.value
  const tripRows = sailings.map(item => [item.code, item.origin.name + ' → ' + item.destination.name, item.vessel.name, new Date(item.departureAt).toLocaleTimeString('en-PH',{hour:'numeric',minute:'2-digit'}), (item.vessel.passengerCapacity-item.availableSeats) + ' / ' + item.vessel.passengerCapacity, item.status])
  const bookingRows = bookings.filter(item=>(bookingStatusFilter.value==='ALL'||item.status===bookingStatusFilter.value)&&`${item.reference} ${item.owner.fullName} ${item.bookingChannel === 'WALK_IN' ? 'walk-in' : item.owner.email} ${item.sailing.origin.name} ${item.sailing.destination.name} ${item.status}`.toLowerCase().includes(bookingSearch.value.trim().toLowerCase())).map(item => [item.reference,item.bookingChannel === 'WALK_IN' ? item.bookingPassengers_on_booking[0]?.fullName || item.owner.fullName : item.owner.fullName,item.sailing.origin.name + ' → ' + item.sailing.destination.name,new Date(item.sailing.departureAt).toLocaleTimeString('en-PH',{hour:'numeric',minute:'2-digit'}),'PHP ' + item.total.toLocaleString(),item.status])
  const passengerRows = passengerRecords.value.map(person => { const account = person.booking.owner.email.endsWith('@walkin.barkolink.invalid') ? 'Walk-in (no account)' : `${person.booking.owner.fullName} · ${person.booking.owner.email}`; return {row:[person.fullName,person.passengerType,person.booking.reference,person.booking.sailing.code,account,person.ticketStatus],search:`${person.fullName} ${person.passengerType} ${person.booking.reference} ${person.booking.sailing.code} ${account} ${person.ticketStatus}`.toLowerCase(),status:person.ticketStatus} }).filter(record=>(passengerStatusFilter.value==='ALL'||record.status===passengerStatusFilter.value)&&record.search.includes(passengerSearch.value.trim().toLowerCase())).map(record=>record.row)
  const userRows = databaseUsers.value.map(user => [user.fullName,user.email,accountRoleLabel(user.role),new Date(user.createdAt).toLocaleDateString('en-PH',{year:'numeric',month:'short',day:'numeric'}),'ACTIVE'])
  const rows = section.value === 'trips' || section.value === 'dashboard' ? tripRows : section.value === 'bookings' ? bookingRows : section.value === 'users' ? userRows : section.value === 'passengers' || section.value === 'manifest' || section.value === 'check-in' || section.value === 'boarding' ? passengerRows : []
  const allRows = rows
  return { ...base, eyebrow: databaseError.value ? 'DATABASE CONNECTION' : base.eyebrow, count: allRows.length, rows: allRows }
})
const aggregateCount = (rows?: Array<{_count:number}>) => rows?.[0]?._count ?? 0
const checkedInCount = computed(() => aggregateCount(dashboardStats.value?.checkedInPassengers))
const boardedCount = computed(() => aggregateCount(dashboardStats.value?.boardedPassengers))
const passengerCount = computed(() => aggregateCount(dashboardStats.value?.allPassengers))
const remainingCount = computed(() => Math.max(0,passengerCount.value-checkedInCount.value))
const boardingPercent = computed(() => passengerCount.value?Math.round(checkedInCount.value/passengerCount.value*100):0)
const metrics = computed(() => [{label:"Today's sailings",value:dashboardStats.value?String(aggregateCount(dashboardStats.value.todaySailings)):'—',note:'Departures today',tone:'blue',icon:boatOutline},{label:"Today's bookings",value:dashboardStats.value?String(aggregateCount(dashboardStats.value.todayBookings)):'—',note:'Created today',tone:'mint',icon:ticketOutline},{label:'Checked in',value:dashboardStats.value?String(checkedInCount.value):'—',note:'Passenger progress',tone:'amber',icon:scanOutline},{label:'Cancelled',value:dashboardStats.value?String(aggregateCount(dashboardStats.value.cancelledBookings)):'—',note:'All reservations',tone:'coral',icon:logOutOutline}])
function handleAdminAction() {
  if (section.value === 'users') {
    userError.value = ''
    createdAccount.value = null
    Object.assign(userForm,{fullName:'',email:'',phone:'',role:'PASSENGER',password:''})
    showUserModal.value = true
    return
  }
  if (section.value === 'check-in' || section.value === 'boarding') { window.location.href = '/staff/boarding'; return }
  if (section.value === 'manifest' || section.value === 'reports') {
    const csv = [current.value.columns, ...current.value.rows].map(row => row.map((value: unknown) => '"' + String(value).replaceAll('"', '""') + '"').join(',')).join('\n')
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); const link = document.createElement('a'); link.href = url; link.download = section.value + '-sample.csv'; link.click(); URL.revokeObjectURL(url); return
  }
  newRecordName.value = ''
  showActionModal.value = true
}
async function cancelBookingByReference(reference:string){const item=databaseBookings.value.find(booking=>booking.reference===reference);if(!staffDataConnect||!item||item.status!=='CONFIRMED'||cancellingReference.value)return;if(new Date(item.sailing.departureAt)<=new Date()){databaseError.value='Departed sailings cannot be cancelled.';return}if(!window.confirm(`Cancel reservation ${item.reference} and return ${item.passengerCount} seat(s) to the sailing?`))return;cancellingReference.value=reference;databaseError.value='';try{await adminCancelBooking(staffDataConnect,{bookingId:item.id,sailingCode:item.sailing.code,passengerCount:item.passengerCount});await loadAdminData()}catch(error){databaseError.value=(error as Error).message||'Could not cancel the booking.'}finally{cancellingReference.value=''}}
async function generateUserPassword(){
  if(!functions)return
  generatingPassword.value=true;userError.value=''
  try{const generate=httpsCallable<null,{password:string}>(functions,'generateTemporaryPassword');const result=await generate(null);userForm.password=result.data.password}
  catch(error){userError.value=(error as Error).message||'Could not generate a password.'}
  finally{generatingPassword.value=false}
}
async function createManagedUser(){
  if(!functions||creatingUser.value)return
  creatingUser.value=true;userError.value=''
  try{
    const create=httpsCallable<{fullName:string;email:string;password:string;role:string},{uid:string;email:string;fullName:string;role:string}>(functions,'createManagedUser')
